fn solve(x: i8, y: i8, z: i8) -> i8 {
    // Under the precondition:
    //   x >= 1, y >= 1, z >= 1
    //   y + 2*z <= x
    //
    // we have:
    //   numerator  = x - z >= y + z > 0
    //   denominator = y + z >= 2 > 0
    //
    // Therefore integer division truncates toward zero, which for positive
    // values yields the floor of the quotient.
    let numerator = x - z;
    let denominator = y + z;
    numerator / denominator
}

